75	// What follows one conversation item: G-code markers and runs of changes, in
76	// seq order. Consecutive changes form one block, which draws as one group.
77	type TimelineBlock =
78	  | { kind: 'marker'; seq: number; marker: GcodeMarkerInfo }
79	  | { kind: 'changes'; seq: number; changes: ChangeInfo[] }
80	  | { kind: 'work'; seq: number; work: WorkInfo[] };
81	
82	function timeline(markers: GcodeMarkerInfo[], changes: ChangeInfo[], work: WorkInfo[] = []): TimelineBlock[] {
83	  const items = [
84	    ...markers.map((marker) => ({ seq: marker.seq, marker, change: undefined, work: undefined })),
85	    ...changes.map((change) => ({ seq: change.seq, marker: undefined, change, work: undefined })),
86	    ...work.map((entry) => ({ seq: entry.seq, marker: undefined, change: undefined, work: entry })),
87	  ].sort((a, b) => a.seq - b.seq);
88	  const blocks: TimelineBlock[] = [];
89	  for (const item of items) {
90	    const previous = blocks[blocks.length - 1];
91	    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
92	    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
93	    else if (item.work && previous?.kind === 'work') previous.work.push(item.work);
94	    else if (item.work) blocks.push({ kind: 'work', seq: item.seq, work: [item.work] });
95	    else blocks.push({ kind: 'marker', seq: item.seq, marker: item.marker! });
96	  }
97	  return blocks;
98	}
99	
100	function TimelineBlocks({ blocks, restorePoints, onRevert, onWorkCancel, readOnly, markerActions }: {
101	  blocks: TimelineBlock[];
102	  markerActions?: MarkerActions;
103	  onWorkCancel?: (id: string) => void;
104	  readOnly?: boolean;
105	  restorePoints: RestorePointInfo[];
106	  onRevert?: (versionId: string) => void;
107	}) {
108	  return (
109	    <>
110	      {blocks.map((block) =>
111	        block.kind === 'marker' ? (
112	          <GcodeMarker key={`marker-${block.marker.id}`} marker={block.marker} actions={markerActions} />
113	        ) : block.kind === 'work' ? (
114	          collapseWork(block.work).map(({ work, times }) => (
115	            <WorkCard key={work.id} work={work} times={times} onCancel={onWorkCancel ?? (() => {})} readOnly={readOnly || !onWorkCancel} />
116	          ))
117	        ) : (
118	          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} restorePoints={restorePoints} onRevert={onRevert} />
119	        ),
120	      )}
121	    </>
122	  );
123	}
