125	// One thread item: a message and the Agent's replies to it. In the project
126	// chat every assistant message that answers the same person's message joins
127	// that message's turn, however many tool calls split the model's reply into
128	// messages. The printer panel keeps one item per message.
129	interface Turn {
130	  anchor: Message;
131	  replies: Message[];
132	}
133	
134	// "Opened find_my_hollow.3mf as a new project · you · 12:16": the file that
135	// replaced the project, who opened it and when. A saved project reopening
136	// with its chat is not new: its note follows the chat's earlier messages.
137	function openedLine(message: Message, report: FileReport, isFirst: boolean): ReactNode {
138	  const files = report.loads.flatMap((load) => load.files);
139	  const name = (files[0] ?? '').split(/[\\/]/).pop() || 'a file';
140	  const text = [`Opened ${name}${files.length > 1 ? ` and ${files.length - 1} more` : ''}${isFirst ? ' as a new project' : ''}`,
141	    report.startedBy === 'agent' ? 'Agent' : 'you', message.createdAt ? chatTimestamp(message.createdAt) : '']
142	    .filter(Boolean).join(' · ');
143	  return <div className="message note" role="status">
144	    <span className="note-text" title={text}>{text}</span>
145	  </div>;
146	}
