148	export function turnsOf(messages: Message[], perMessage: boolean): Turn[] {
149	  const turns: Turn[] = [];
150	  for (const message of messages) {
151	    const current = turns[turns.length - 1];
152	    if (!perMessage && current && message.role === 'assistant' && message.inReplyTo === current.anchor.id)
153	      current.replies.push(message);
154	    else turns.push({ anchor: message, replies: [] });
155	  }
156	  return turns;
157	}
