159	export function MessageList({
160	  messages,
161	  attachments,
162	  streamingMessageId,
163	  toolActivities,
164	  gcodeMarkers,
165	  markerActions,
166	  changes,
167	  work = [],
168	  onWorkCancel,
169	  restorePoints = [],
170	  onRevert,
171	  onRetry,
172	  onToolCancel,
173	  onSaveProposal,
174	  onUndoReceipt,
175	  onSend,
176	  replyDisabled = false,
177	  readOnly = false,
178	  endNotice,
179	  printerBlocks,
180	  onUndoAdd,
181	  onInstallPlugin,
182	  renderActivity,
183	  onScrolledChange,
184	}: Props) {
185	  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
186	  const listRef = useRef<HTMLDivElement>(null);
187	  const [followBottom, setFollowBottom] = useState(true);
188	
189	  const handleScroll = () => {
190	    const list = listRef.current;
191	    if (!list) return;
192	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
193	    setFollowBottom(distanceFromBottom < 24);
194	    onScrolledChange?.(list.scrollTop > 0);
195	  };
196	
197	  useEffect(() => () => onScrolledChange?.(false), [onScrolledChange]);
198	
199	  useLayoutEffect(() => {
200	    const list = listRef.current;
201	    if (list && followBottom) list.scrollTop = list.scrollHeight;
202	  }, [messages, toolActivities, gcodeMarkers, changes, printerBlocks, followBottom]);
203	  const printerPanel = printerBlocks !== undefined;
204	
205	  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
206	  const turns = turnsOf(messages, printerPanel);
207	  const messagesOf = (turn: Turn) => [turn.anchor, ...turn.replies];
208	  // A change, work entry or G-code marker follows a message or one of its
209	  // tool activities; all of them place it after that message's turn.
210	  const turnOfItem = new Map<string, string>();
211	  for (const turn of turns)
212	    for (const message of messagesOf(turn)) {
213	      turnOfItem.set(message.id, turn.anchor.id);
214	      for (const activity of activitiesOf(message.id)) turnOfItem.set(activity.actionId, turn.anchor.id);
215	    }
216	  // A save the person approved, and its Undo, change the setup; the receipt
217	  // says so, and draws in place of the change rows.
218	  const receipted = new Set([
219	    ...toolActivities.filter((activity) => activity.approves).map((activity) => activity.actionId),
220	    ...messages.filter((message) => message.receipt).map((message) => message.id),
221	  ]);
222	  const changesAfter = (turnId: string) =>
223	    changes.filter((change) => turnOfItem.get(change.afterId) === turnId && !receipted.has(change.afterId));
224	  const leadingChanges = changes.filter((change) => !turnOfItem.has(change.afterId));
225	  // Work keeps the place it started at: after the item that was last then,
226	  // so a message that arrived later reads below it.
227	  const workAfter = (turnId: string) => work.filter((entry) => turnOfItem.get(entry.afterId) === turnId);
228	  const leadingWork = work.filter((entry) => !turnOfItem.has(entry.afterId));
229	  const markersAfter = (turnId: string) => gcodeMarkers.filter((marker) => turnOfItem.get(marker.afterId) === turnId);
230	  const printerBlockViews = (messageId: string) =>
231	    (printerBlocks ?? [])
232	      .filter((block) => block.afterMessageId === messageId)
233	      .sort((a, b) => a.seq - b.seq)
234	      .map((block) => <PrinterBlockView key={block.id} block={block} onUndoAdd={onUndoAdd} onInstallPlugin={onInstallPlugin} />);
235	  const leadingMarkers = gcodeMarkers.filter((marker) => !turnOfItem.has(marker.afterId));
236	
237	  // A message's bubble, or null for a tool-only reply that has nothing to
238	  // say. A file's load report is for the model: the person sees the card of
239	  // what OrcaSlicer said only when the Agent could not speak about it.
240	  // Otherwise the event that started the Agent's turn gets a row of its own
241	  // when the load replaced the project, as the Chat/System Line; an import
242	  // into the open project has its change row ("Import Object: …") already.
243	  const bubble = (message: Message, after?: ReactNode): ReactNode => {
244	    if (message.role === 'note' && message.fileReport) {
245	      if (message.fileReportCard) return <FileNotesCard report={message.fileReport} />;
246	      return message.fileReport.projectOpened ? openedLine(message, message.fileReport, messages[0]?.id === message.id) : null;
247	    }
248	    // Chat/Receipt: a preset the person saved from a proposal, in the same
