250	    // and the receipt stays to say so, as an added printer's does.
251	    if (message.role === 'note' && message.receipt) {
252	      const receipt = message.receipt;
253	      const removed = receipt.undone && receipt.undo?.newCopy;
254	      return (
255	        <div className={receipt.undone ? 'printer-added printer-added-removed' : 'printer-added'} role="status">
256	          <span className="printer-notice-heading">
