266	          ) : (
267	            <span className="printer-added-detail">
268	              <small>{receipt.detail}</small>
269	              {receipt.undo && onUndoReceipt && !readOnly && (
270	                <button type="button" className="panel-link-button printer-added-undo" disabled={replyDisabled}
