300	    // work instead; the printer panel names it here while streaming. Once
301	    // settled still empty, nothing is drawn. A failed or stopped turn
302	    // always still renders, so its error and Retry stay reachable.
303	    const emptyTurn =
304	      message.role === 'assistant' &&
305	      !message.text &&
306	      photos.length === 0 &&
307	      otherAttachments.length === 0 &&
308	      message.state !== 'stopped' &&
309	      !(message.state === 'failed' && message.error);
310	    const streaming = message.id === streamingMessageId;
311	    if (emptyTurn && printerPanel && streaming)
312	      return (
313	        // Chat/System Line: a quiet line of status while the model works.
314	        <div className="message assistant">
315	          <div className="printer-activity" role="status">
316	            <span className="jp-icon jp-icon-rotate-cw" aria-hidden="true" />
